+    private getRemainingRefundableQuantity(line: OrderDetailFragment['lines'][number]): number {
+        let refundedCount = 0;
+        for (const payment of this.order.payments ?? []) {
+            for (const refund of payment.refunds) {
+                if (refund.state === 'Failed') {
+                    continue;
+                }
+                for (const refundLine of refund.lines) {
+                    if (refundLine.orderLineId === line.id) {
+                        refundedCount += refundLine.quantity;
+                    }
+                }
+            }
+        }
+        return Math.max(0, line.orderPlacedQuantity - refundedCount);
